//! Authenticated original checker observations, never generated by the native port.
use crate::{
    model_family_process::{json_file, relative, require, Held},
    seal::Result,
};
use serde_json::Value;
use std::{
    cell::RefCell,
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
};
pub(crate) struct Original {
    pub report: Value,
    pub manifest: Value,
    held: Vec<Held>,
    absent: Vec<PathBuf>,
    root: PathBuf,
    current: RefCell<Option<crate::driver_daemon_check::CurrentCatalogAdmission>>,
}
impl Original {
    pub fn open(
        root: &Path,
        directory: &Path,
        manifest_sha: &str,
        retired: &[(&str, &str)],
        expect_absent: bool,
        required_sources: &[&str],
    ) -> Result<Self> {
        let manifest_path = directory.join("manifest.json");
        let manifest_pin = Held::open(&manifest_path, 4 * 1024 * 1024, false)?;
        require(
            manifest_pin.pin()["sha256"] == manifest_sha,
            "model family original manifest SHA changed",
        )?;
        let manifest: Value = json_file(&manifest_path, 4 * 1024 * 1024)?;
        require(
            manifest["version"] == 1
                && manifest["origin"] == "unchanged original checker"
                && manifest["native_port_generated_expected"] == false,
            "model family original provenance changed",
        )?;
        let source_inputs = manifest["source_inputs"]
            .as_object()
            .ok_or("original source input map missing")?;
        for &(name, sha) in retired {
            require(
                source_inputs.get(name).is_some_and(|p| p["sha256"] == sha),
                "model family historical retired source pin missing or changed",
            )?;
        }
        for &name in required_sources {
            require(
                source_inputs.contains_key(name),
                "required original runtime source pin missing",
            )?;
        }
        let mut held = vec![manifest_pin];
        let mut absent = Vec::new();
        for (name, seal) in source_inputs {
            let path = root.join(relative(name)?);
            if expect_absent && retired.iter().any(|(n, _)| *n == name) {
                absent.push(path);
                continue;
            }
            let input = Held::open(&path, 16 * 1024 * 1024, false)?;
            input.expect(seal)?;
            held.push(input);
        }
        let files = manifest["files"]
            .as_object()
            .ok_or("original file map missing")?;
        require(
            !files.is_empty() && files.len() <= 256 && files.contains_key("report.json"),
            "original report file roster invalid",
        )?;
        let mut total = 0u64;
        for (name, seal) in files {
            let path = directory.join(relative(name)?);
            let input = Held::open(&path, 16 * 1024 * 1024, false)?;
            input.expect(seal)?;
            total = total
                .checked_add(
                    seal["bytes"]
                        .as_u64()
                        .ok_or("original file byte count missing")?,
                )
                .ok_or("original fixture size overflow")?;
            require(total <= 128 * 1024 * 1024, "original fixture exceeds bound")?;
            held.push(input);
        }
        let report: Value = json_file(&directory.join("report.json"), 4 * 1024 * 1024)?;
        let result = Self {
            report,
            manifest,
            held,
            absent,
            root: root.to_owned(),
            current: RefCell::new(None),
        };
        result.verify()?;
        Ok(result)
    }
    pub fn verify(&self) -> Result<()> {
        if let Some(current) = self.current.borrow().as_ref() {
            current.verify()?;
        }
        for path in &self.absent {
            match fs::symlink_metadata(path) {
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                _ => return Err("retired model family source reappeared".into()),
            }
        }
        for input in &self.held {
            input.verify()?;
        }
        require(
            fs::symlink_metadata(&self.root)?.is_dir(),
            "model source root changed",
        )
    }
    pub fn cached_admission(&self) -> Result<Option<(PathBuf, String)>> {
        self.current
            .borrow()
            .as_ref()
            .ok_or("current family catalog admission missing")?
            .cached_admission()
    }
    pub fn catalog_sources(&self, catalog: &Path, kinds: &[&str]) -> Result<()> {
        if self.current.borrow().is_none() {
            let models = self.manifest["models"]
                .as_object()
                .ok_or("original model roster missing")?
                .iter()
                .map(|(name, seal)| {
                    Ok((
                        name.clone(),
                        seal["sha256"]
                            .as_str()
                            .ok_or("original model hash missing")?
                            .to_owned(),
                    ))
                })
                .collect::<Result<BTreeMap<String, String>>>()?;
            let receipt = std::env::var_os("MODEL_FAMILY_CURRENT_CATALOG_RECEIPT")
                .ok_or("explicit model family current catalog receipt required")?;
            let sha = std::env::var("MODEL_FAMILY_CURRENT_CATALOG_RECEIPT_SHA256")?;
            let checkout = std::env::var("EXPECTED_SOURCE")?;
            let admitted = crate::driver_daemon_check::CurrentCatalogAdmission::open(
                &self.root,
                catalog,
                Path::new(&receipt),
                &sha,
                &models,
                &checkout,
            )?;
            *self.current.borrow_mut() = Some(admitted);
        }
        self.current
            .borrow()
            .as_ref()
            .ok_or("current catalog admission missing")?
            .verify()?;
        let pointer: Value = json_file(&catalog.join("current.json"), 4 * 1024 * 1024)?;
        let generation = pointer["generation"]
            .as_str()
            .filter(|s| s.len() == 64 && s.bytes().all(|b| b.is_ascii_hexdigit()))
            .ok_or("model family catalog generation invalid")?;
        let index: Value = json_file(
            &catalog.join(generation).join("index.json"),
            4 * 1024 * 1024,
        )?;
        let bundles = index["bundles"]
            .as_array()
            .ok_or("model family catalog bundles missing")?;
        let models = self.manifest["models"]
            .as_object()
            .ok_or("original compiled model map missing")?;
        let index_pin = Held::open(
            &catalog.join(generation).join("index.json"),
            4 * 1024 * 1024,
            false,
        )?;
        require(
            index_pin.pin()["sha256"] == generation,
            "model family catalog index generation hash changed",
        )?;
        for &kind in kinds {
            for camera in [[1344, 760], [1928, 1208]] {
                let matches = bundles
                    .iter()
                    .filter(|b| b["kind"] == kind && b["camera"] == serde_json::json!(camera))
                    .collect::<Vec<_>>();
                require(
                    matches.len() == 1,
                    "model family catalog lacks unique camera bundle",
                )?;
                let name = matches[0]["directory"]
                    .as_str()
                    .ok_or("model family catalog bundle path missing")?;
                let descriptor: Value = json_file(
                    &catalog
                        .join(generation)
                        .join(relative(name)?)
                        .join("pipeline.json"),
                    4 * 1024 * 1024,
                )?;
                require(
                    descriptor["kind"] == kind && descriptor["camera"] == serde_json::json!(camera),
                    "model family catalog pipeline kind/camera changed",
                )?;
                let expected = if kind == "driving" {
                    BTreeMap::from([("driving", "driving_tinygrad.pkl".to_owned())])
                } else {
                    BTreeMap::from([
                        ("model", "dmonitoring_model_tinygrad.pkl".to_owned()),
                        ("metadata", "dmonitoring_model_metadata.pkl".to_owned()),
                        (
                            "warp",
                            format!("dm_warp_{}x{}_tinygrad.pkl", camera[0], camera[1]),
                        ),
                    ])
                };
                for (role, model) in expected {
                    let seal = models
                        .get(&model)
                        .ok_or("original compiled model pin missing")?;
                    require(
                        descriptor["sources"][role] == seal["sha256"],
                        "native startup catalog model differs from original source artifact",
                    )?;
                }
            }
        }
        Ok(())
    }
}
